<script>document.addEventListener('DOMContentLoaded',()=>{if(window.homeItemOrderReady)return;window.homeItemOrderReady=true;document.querySelectorAll('.home-builder input[type="hidden"][name$="[key]"]').forEach(key=>{const match=key.name.match(/^content\[(slides|items)\]\[(\d+)\]\[key\]$/);if(!match)return;const panel=key.closest('.hb-panel');if(!panel||panel.querySelector('input[data-item-order]'))return;const label=document.createElement('label');label.className='hb-item-order';label.textContent='Orden ';const input=document.createElement('input');input.type='number';input.min='0';input.name=`content[${match[1]}][${match[2]}][sort_order]`;input.value=(Number(match[2])+1)*10;input.dataset.itemOrder='1';input.style.width='70px';label.appendChild(input);key.after(label)});});</script>
